pragma solidity >=0.4.0;

import "src/PaidInvoiceBook.sol";

abstract contract DeployHelper34 is PaidInvoiceBook {
    struct FoundryPpConstructorArgs {
        address treasury; address expectedBuyer; bytes32 expectedOrderId; address expectedAsset; bytes32 expectedPolicyHash;
    }
}

function encodeArgs34(DeployHelper34.FoundryPpConstructorArgs memory args) pure returns (bytes memory) {
    return abi.encode(args.treasury, args.expectedBuyer, args.expectedOrderId, args.expectedAsset, args.expectedPolicyHash);
}

